.shell { display: flex; min-height: 100vh; }
.sidebar {
  position: fixed; inset: 0 auto 0 0; width: var(--sidebar); z-index: 30; display: flex; flex-direction: column;
  padding: 22px 14px 18px; color: var(--side-text);
  background: radial-gradient(120% 40% at 0% 0%, #de325d2e, transparent 60%), linear-gradient(180deg, var(--ink-900), var(--ink-950));
  border-right: 1px solid #ffffff0a;
}
.brand { display: flex; align-items: center; gap: 2px; padding: 4px 10px 28px; color: #fff; font-size: 25px; font-weight: 750; letter-spacing: -1.1px; }
.brand-mark { display: inline-grid; place-items: center; width: 32px; height: 32px; margin-right: 10px; border-radius: 10px; background: var(--brand-gradient); color: #fff; font-size: 19px; font-weight: 800; letter-spacing: 0; box-shadow: 0 6px 18px #de325d55, inset 0 1px 0 #ffffff40; }
.brand-dot { color: var(--side-accent); }
.nav-label { font-size: 10px; font-weight: 650; letter-spacing: 1.4px; text-transform: uppercase; color: var(--side-muted); padding: 0 12px; margin: 6px 0 8px; }
.nav { display: flex; flex-direction: column; gap: 2px; }
.nav-link { position: relative; display: flex; align-items: center; gap: 11px; padding: 9px 12px; border-radius: 10px; color: var(--side-text); font-size: 13.5px; font-weight: 500; transition: background .15s, color .15s; }
.nav-link .icon { transition: color .15s; }
.nav-link .icon { width: 18px; height: 18px; }
.nav-link:hover { background: #ffffff0d; color: #fff; }
.nav-link.active { background: linear-gradient(90deg, #de325d33, #de325d0d); color: #fff; box-shadow: inset 0 0 0 1px #de325d33; }
.nav-link.active .icon { color: var(--side-accent); }
.nav-link.active::before { content: ''; position: absolute; left: -14px; top: 9px; bottom: 9px; width: 3px; border-radius: 0 3px 3px 0; background: var(--accent); }
.nav-count { margin-left: auto; font-size: 11px; font-weight: 650; padding: 1px 7px; border-radius: 20px; background: #de325d40; color: #ffb3c6; }
.sidebar-footer { margin-top: auto; padding: 16px 12px 0; border-top: 1px solid #ffffff14; font-size: 11.5px; color: var(--side-muted); line-height: 1.6; }
.sidebar-footer strong { color: var(--side-strong); font-weight: 600; display: flex; align-items: center; gap: 7px; }
.live-dot { width: 7px; height: 7px; border-radius: 50%; background: #6fc49a; box-shadow: 0 0 0 3px #6fc49a26; display: inline-block; }

.workspace { margin-left: var(--sidebar); flex: 1; min-width: 0; display: flex; flex-direction: column; }
.topbar {
  position: sticky; top: 0; z-index: 20; height: 60px; display: flex; align-items: center; gap: 16px; padding: 0 32px;
  background: #f9f7f7e6; backdrop-filter: blur(10px); border-bottom: 1px solid var(--border);
}
.topbar-context { display: flex; align-items: center; gap: 10px; min-width: 0; font-size: 13px; color: var(--text-2); }
.topbar-context strong { color: var(--text); font-weight: 600; }
.topbar-right { margin-left: auto; display: flex; align-items: center; gap: 12px; }
.actor-field { display: flex; align-items: center; gap: 8px; height: 34px; padding: 0 4px 0 10px; border: 1px solid var(--border); border-radius: 9px; background: var(--surface); font-size: 12px; color: var(--muted); }
.actor-field input { border: 0; outline: 0; background: transparent; width: 150px; font-size: 13px; color: var(--text); padding: 0 6px; }
.actor-field:focus-within { border-color: var(--accent); box-shadow: 0 0 0 3px var(--focus); }
.pill-sim { display: inline-flex; align-items: center; gap: 6px; height: 26px; padding: 0 10px; border-radius: 20px; font-size: 11.5px; font-weight: 600; color: var(--st-good-ink); background: var(--st-good-wash); }
.main { padding: 28px 32px 48px; width: 100%; max-width: 1480px; margin: 0 auto; }
.footer-seal { padding: 14px 32px 24px; font-size: 11.5px; color: var(--muted); display: flex; gap: 14px; flex-wrap: wrap; justify-content: space-between; max-width: 1480px; margin: 0 auto; width: 100%; }

/* ---------- Page header ---------- */
.page-head { display: flex; align-items: flex-end; justify-content: space-between; gap: 20px; margin-bottom: 22px; flex-wrap: wrap; }
.eyebrow { font-size: 11px; font-weight: 700; letter-spacing: 1.3px; text-transform: uppercase; color: var(--accent); margin-bottom: 6px; }
.page-title { font-size: 28px; line-height: 1.15; font-weight: 700; letter-spacing: -.8px; color: var(--text); }
.page-sub { margin-top: 6px; color: var(--text-2); font-size: 13.5px; max-width: 760px; }
.actions { display: flex; align-items: center; gap: 8px; flex-wrap: wrap; }

/* ---------- Buttons ---------- */
.btn {
  display: inline-flex; align-items: center; justify-content: center; gap: 7px; height: 36px; padding: 0 14px; border-radius: 9px;
  border: 1px solid var(--border-strong); background: var(--surface); color: var(--text); font-size: 13px; font-weight: 550; white-space: nowrap;
  transition: background .15s, border-color .15s, box-shadow .15s, transform .05s;
}
.meter.tall { height: 18px; border-radius: 7px; }
.meter-track { background: var(--surface-3); }
.progress { height: 6px; border-radius: 6px; background: var(--surface-3); overflow: hidden; }
.progress > span { display: block; height: 100%; border-radius: 6px; background: var(--st-good); transition: width .35s ease; }
.progress.info > span { background: var(--series-1); }

/* ---------- Responsive ---------- */
@media (max-width: 1200px) {
  .grid-4 { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .grid-3 { grid-template-columns: repeat(2, minmax(0, 1fr)); }
}
@media (max-width: 960px) {
  :root { --sidebar: 72px; }
  .sidebar { padding: 18px 10px; }
  .brand { font-size: 0; justify-content: center; padding: 0 0 22px; }
  .brand-mark { font-size: 32px; margin: 0; }
  .brand-dot, .nav-label, .nav-link span:not(.nav-count), .sidebar-footer { display: none; }
  .nav-link { justify-content: center; padding: 11px; }
  .nav-count { position: absolute; top: 2px; right: 2px; font-size: 9.5px; padding: 0 5px; }
  .nav-link.active::before { left: -10px; }
  .grid-2, .grid-3 { grid-template-columns: 1fr; }
  .topbar, .main { padding-left: 20px; padding-right: 20px; }
}
@media (max-width: 640px) {
  :root { --sidebar: 0px; }
  .sidebar { inset: auto 0 0 0; width: 100%; height: 60px; padding: 0 6px; flex-direction: row; }
  .brand, .sidebar-footer { display: none; }
  .nav { flex-direction: row; width: 100%; justify-content: space-around; }
  .nav-link { flex-direction: column; gap: 2px; padding: 8px 6px; font-size: 10px; }
  .nav-link span:not(.nav-count) { display: block; font-size: 10px; }
  .nav-link.active::before { left: 50%; top: -1px; bottom: auto; width: 18px; height: 3px; transform: translateX(-50%); border-radius: 0 0 3px 3px; }
  .workspace { margin: 0 0 60px; }
  .topbar { padding: 0 16px; }
  .actor-field input { width: 100px; }
  .pill-sim { display: none; }
  .main { padding: 20px 16px 32px; }
  .grid-4 { grid-template-columns: 1fr; }
  .form-grid { grid-template-columns: 1fr; }
  .page-title { font-size: 22px; }
  .sheet { width: 100vw; }
}
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after { animation: none !important; transition: none !important; }
}

